mapper.insert:
INSERT INTO cs_capability_idempotency(
    storage_key_hash, request_fingerprint_hash, status,
    owner_token, lease_until, result_json, result_schema_version,
    created_at, updated_at
) VALUES (
    #{keyHash}, #{fingerprintHash}, #{status},
    #{ownerToken}, #{leaseUntil}, NULL, NULL, #{now}, #{now}
)

mapper.update:
UPDATE cs_capability_idempotency
SET owner_token = #{newOwnerToken},
    lease_until = #{newLeaseUntil},
    updated_at = #{now}
WHERE storage_key_hash = #{keyHash}
  AND request_fingerprint_hash = #{fingerprintHash}
  AND status = #{status}
  AND owner_token = #{oldOwnerToken}
  AND lease_until = #{oldLeaseUntil}

UPDATE cs_capability_idempotency
SET status = #{completedStatus},
    result_json = #{resultJson},
    result_schema_version = #{resultSchemaVersion},
    lease_until = 0,
    updated_at = #{now}
WHERE storage_key_hash = #{keyHash}
  AND request_fingerprint_hash = #{fingerprintHash}
  AND status = #{inProgressStatus}
  AND owner_token = #{ownerToken}

UPDATE cs_capability_idempotency
SET lease_until = #{leaseUntil}, updated_at = #{now}
WHERE storage_key_hash = #{keyHash}
  AND request_fingerprint_hash = #{fingerprintHash}
  AND status = #{status}
  AND owner_token = #{ownerToken}

mapper.delete:
DELETE FROM cs_capability_idempotency
WHERE storage_key_hash = #{keyHash}
  AND status = #{status}
  AND owner_token = #{ownerToken}
